using System.Security.Cryptography;
using System.Text.Json;
using LineThrottle156;
namespace ThreeLap158;
public static class Freeze158 {
 static string Source=>Path.Combine(Study156.Root,"tools/robust-three-lap");
 static Dictionary<string,string> Hashes()=>Directory.GetFiles(Source).Where(p=>p.EndsWith(".cs",StringComparison.Ordinal)||p.EndsWith(".csproj",StringComparison.Ordinal)||p.EndsWith("generate158.mjs",StringComparison.Ordinal)||p.EndsWith("packages.lock.json",StringComparison.Ordinal)).Order().ToDictionary(p=>Path.GetFileName(p)!,p=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))))!;
 public static void Create(string label){var manifest=Study156.Read<JsonElement>(Path.Combine(Program158.Doc,"scenarios-frozen.json"));var rows=Directory.GetFiles(Path.Combine(Program158.Doc,"native"),"*-result.json").Select(p=>(Path:p,Data:Study156.Read<JsonElement>(p))).Where(p=>p.Data.GetProperty("Pass").GetBoolean()&&!p.Data.GetProperty("Baseline").GetBoolean()&&p.Data.GetProperty("CompletedLaps").GetInt32()==3).ToArray();if(Directory.GetFiles(Path.Combine(Program158.Doc,"native"),"*-result.json").Select(p=>Study156.Read<JsonElement>(p)).Any(x=>x.GetProperty("Validation").GetBoolean()))throw new InvalidOperationException("Validation already started; cannot refreeze");if(rows.Length==0)throw new InvalidOperationException("No first actual complete native S, validation remains closed");Program158.Save("controller-freeze.json",new{Label=label,Base=Program158.Base,RequiredLaps=3,RequiredTrials=manifest.GetProperty("Scenarios").GetArrayLength(),MinimumIndependentTrials=manifest.TryGetProperty("MinimumIndependentTrials",out var required)?required.GetInt32():5,ScenarioHash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(Program158.Doc,"scenarios-frozen.json")))),Sources=Hashes(),FirstCompleteNative=Path.GetRelativePath(Study156.Root,rows[0].Path).Replace('\\','/'),FirstNativeFingerprint=rows[0].Data.GetProperty("Fingerprint").GetString(),HeldOutcomesRead=false,Scope="Frozen before first held outcome; merge completes before first bend; known A and nominal are development; unseen cases remain held; memoized joint inverse is mechanically derived and bit tested"});Console.WriteLine("Frozen158 before held validation");}
 public static void Check(){var f=Study156.Read<JsonElement>(Path.Combine(Program158.Doc,"controller-freeze.json"));var expected=f.GetProperty("Sources");var actual=Hashes();if(actual.Count!=expected.EnumerateObject().Count())throw new InvalidOperationException("Frozen source inventory changed");foreach(var p in actual)if(!expected.TryGetProperty(p.Key,out var h)||h.GetString()!=p.Value)throw new InvalidOperationException("Frozen controller changed: "+p.Key);var scenario=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(Program158.Doc,"scenarios-frozen.json"))));if(scenario!=f.GetProperty("ScenarioHash").GetString())throw new InvalidOperationException("Frozen validation conditions changed");}
}
